<div class="page-title"><div><h2>قوانین کمیسیون فروش</h2><p class="text-muted">قانون اختصاصی کاربر بر قانون عمومی اولویت دارد. مبنای محاسبه را شفاف انتخاب کنید.</p></div></div>
<section class="card mb-4"><div class="card-header"><h3>افزودن قانون</h3></div><form method="post" action="<?= e(url('plugin/accounting/rules/save')) ?>" class="form-grid four"><?= csrf_field() ?><label>نام قانون<input name="name" required></label><label>فروشنده<select name="user_id"><option value="">قانون عمومی</option><?php foreach (($staff ?? []) as $person): ?><option value="<?= (int) $person['id'] ?>"><?= e($person['full_name']) ?></option><?php endforeach; ?></select></label><label>نوع کمیسیون<select name="commission_type"><option value="percentage">درصدی</option><option value="fixed">مبلغ ثابت</option></select></label><label>مقدار<input name="commission_value" inputmode="decimal" required></label><label>مبنای محاسبه<select name="calculation_basis"><option value="financed_amount">مبلغ تامین‌شده</option><option value="principal_amount">اصل قرارداد</option><option value="collected_amount">مبلغ وصول‌شده</option></select></label><label>حداقل مبلغ<input name="minimum_amount" inputmode="numeric"></label><label>حداکثر مبلغ<input name="maximum_amount" inputmode="numeric"></label><label>زمان محاسبه<select name="calculation_timing"><option value="at_contract_creation">هنگام ایجاد قرارداد</option><option value="after_down_payment">پس از پیش‌پرداخت</option><option value="after_first_installment">پس از قسط اول</option><option value="after_full_settlement">پس از تسویه</option><option value="manual_approval">تأیید دستی</option></select></label><label>اولویت<input name="priority" value="0" inputmode="numeric"></label><label class="check"><input type="checkbox" name="requires_approval" value="1"><span>نیازمند تأیید</span></label><div class="full"><button class="btn btn-primary" type="submit">ذخیره قانون</button></div></form></section>
<section class="card"><div class="table-responsive"><table class="table proma-accounting-table"><thead><tr><th>نام</th><th>کاربر</th><th>نوع</th><th>مقدار</th><th>مبنا</th><th>وضعیت تأیید</th></tr></thead><tbody><?php foreach (($rules ?? []) as $rule): ?><tr><td><?= e($rule['name']) ?></td><td><?= e($rule['user_name'] ?: 'عمومی') ?></td><td><?= $rule['commission_type'] === 'percentage' ? 'درصدی' : 'ثابت' ?></td><td><?= e($rule['commission_value']) ?></td><td><?= e($rule['calculation_basis']) ?></td><td><?= !empty($rule['requires_approval']) ? 'نیازمند تأیید' : 'خودکار' ?></td></tr><?php endforeach; ?><?php if (empty($rules)): ?><tr><td colspan="6" class="empty">قانون اختصاصی ثبت نشده است؛ تنظیمات عمومی استفاده می‌شود.</td></tr><?php endif; ?></tbody></table></div></section>
